function hydrateGeneratedCard(g){let source=C[g.origin];if(!source)return;C[g.id]={...source,id:g.id,cost:0,generated:true,origin:g.origin,fx:{...source.fx},desc:source.desc+' このターン終了時に除外。'};}
for(let g of S.run?.generatedCards||[])hydrateGeneratedCard(g);
function expireGeneratedCards(r){for(let pile of ['hand','draw','discard']){let expired=(r[pile]||[]).filter(id=>C[id]?.generated);r[pile]=(r[pile]||[]).filter(id=>!C[id]?.generated);for(let id of expired)exhaustCard(r,id)}}
keywords.守護='カード使用時に得るブロックにスタック数を加算します。負の値では減少しますが、獲得量は0未満になりません。遺物・プレート・ターン開始時などの自動効果には適用されません。戦闘終了時に消えます。';keywords.鼓動='発動後、エナジーを4消費するごとに1回復。超過分とターンをまたいだ進捗も保持。同じ効果は重複しません。';rich=s=>s.replace(/筋力|除外|ブロック|再生|毒|守護|プレート|鼓動/g,x=>`<strong class="keyword">${x}</strong>`);
function blockValue(r,n,source='card'){return Math.max(0,n+(source==='card'?(r.agility||0):0)+(r.blockBonus||0))}
function gainBlock(r,n,source='card'){r.block+=blockValue(r,n,source)}
needsEnemy=c=>!c.fx.all&&!!(c.fx.d||c.fx.p||c.fx.blockScale||c.fx.totalPoison||c.fx.equalPoison||c.fx.exactBlock||c.fx.breakBlock||c.fx.discardBreak);
previewDamage=function(c,r,e){let f=c.fx;if(f.totalPoison)return r.enemies.filter(x=>x.hp>0).reduce((n,x)=>n+(x.poison||0),0)*f.totalPoison;if(f.equalPoison)return (e?.poison||0)*f.equalPoison;if(f.exactBlock)return Math.max(0,r.block*f.exactBlock+(f.blockDamageIgnoresStrength?0:(r.str||0)));return (f.d||0)+(r.str||0)*(f.strScale||1)+(f.exScale||0)*exhaustedCount(r)+Math.floor((f.blockScale||0)*r.block)};
bonusReady=(c,r)=>!!((c.fx.lowEnergy&&r.hp<=r.max/2)||(c.fx.strBonus&&r.str>=(c.fx.strBonusThreshold??4))||(c.fx.blockScale&&r.block)||(c.fx.exScale&&exhaustedCount(r)));
combatDesc=function(c,r){let d=c.desc,f=c.fx;if(f.d!=null)d=d.replace(f.d+'ダメージ',`<strong class="boost">${previewDamage(c,r,r.enemies[target])}ダメージ</strong>`);if(f.b)d=d.replace(f.b+'ブロック',`<strong class="boost">${blockValue(r,f.b)}ブロック</strong>`);if(f.strengthBlock)d=`<strong class="boost">${blockValue(r,r.str)}</strong>ブロックを得る（現在の筋力）。`;if(f.totalPoison)d=`対象に<strong class="boost">${previewDamage(c,r,null)}</strong>ダメージ（生存している敵全体の毒スタックの総数）。`;if(f.exactBlock)d=`対象に<strong class="boost">${previewDamage(c,r,null)}</strong>ダメージ（現在のブロック${f.exactBlock===1?'と同じ値':'の'+f.exactBlock+'倍'}${f.blockDamageIgnoresStrength?'':'＋筋力'}）。${f.spendBlock?'ブロックをすべて失う。':''}`;if(f.exhaustBlock)d=`<strong class="boost">${blockValue(r,Math.floor(exhaustedCount(r)/2))}</strong>ブロック（使用前の除外済み${exhaustedCount(r)}枚）。除外。`;return d};
card=function(id,action='',extra=''){let r=S.run,active=page==='battle'&&r,c=active?combatCard(id):C[id],desc=active?combatDesc(c,r):c.desc;return `<div class="card-wrap"><button class="card ${c.rarity} ${active?(r.energy>=c.cost?(bonusReady(c,r)?'empowered':'playable'):'unplayable'):''}" ${action?`onclick="${action}"`:''} data-card="${id}"><span class="cost">${c.cost}</span><div class="art">${c.icon}</div><small>${c.rarity.toUpperCase()}${c.generated?' / 生成・ターン終了時除外':c.runOnly?' / 潜在':''}</small><h3>${c.name}</h3><p>${rich(desc)}</p>${extra}</button>${tips(c)?`<aside class="tooltip">${tips(c)}</aside>`:''}</div>`};
exhaustCard=function(r,id,trigger=true){(r.exhausted??=[]).push(id);if(trigger&&r.exhaustEngine)gainBlock(r,4*r.exhaustEngine,'passive')};
base.play=function(i){let r=S.run,c=combatCard(r?.hand[i]);if(!c||r.energy<c.cost||r.pendingChoice||r.pendingDiscard||r.potionTarget!=null)return;let f=c.fx,wasHeartbeat=r.heartbeat,str=r.str;target=r.enemies[target]?.hp>0?target:r.enemies.findIndex(e=>e.hp>0);r.energy-=c.cost;r.hand.splice(i,1);for(let e of f.all?r.enemies.filter(e=>e.hp>0):[r.enemies[target]]){if(!e)continue;if(f.d!=null||f.totalPoison||f.equalPoison||f.exactBlock)for(let h=0;h<(f.h||1);h++)damage(e,previewDamage(c,r,e));if(f.p)e.poison+=f.p;if(f.breakBlock){e.block=0;if(typeof clearArchiveReading==='function')clearArchiveReading(e);}}if(f.selfDamage)damage(r,f.selfDamage);if(f.spendBlock)r.block=0;if(f.discardBreak){if(r.hand.length)r.pendingChoice={kind:'discard',breakTarget:target,remaining:f.discardCount||1};else if(r.enemies[target]){r.enemies[target].block=0;if(typeof clearArchiveReading==='function')clearArchiveReading(r.enemies[target]);}}if(f.b)gainBlock(r,f.b);if(f.strengthBlock)gainBlock(r,str*f.strengthBlock);if(f.exhaustBlock)gainBlock(r,Math.floor(exhaustedCount(r)/2)*f.exhaustBlock);for(let recovered=0;recovered<(f.recover||0)&&r.discard.length&&r.hand.length<10;recovered++)r.hand.push(r.discard.splice(Math.floor(Math.random()*r.discard.length),1)[0]);r.hp=Math.min(r.max,r.hp+(f.heal||0));r.str+=(f.s||0)+(f.strBonus&&str>=4?f.strBonus:0);if(f.doubleStr){r.str*=f.strMultiplier||2;r.tempStr=(r.tempStr||0)*(f.strMultiplier||2)}r.energy+=(f.energy||0)+(f.lowEnergy&&r.hp<=r.max/2?f.lowEnergy:0);for(let sacrificed=0;sacrificed<(f.sacrifice||0)&&r.hand.length;sacrificed++)exhaustCard(r,r.hand.splice(Math.floor(Math.random()*r.hand.length),1)[0]);if(f.ex)exhaustCard(r,c.id);else r.discard.push(c.id);if(f.engine)r.exhaustEngine=(r.exhaustEngine||0)+f.engine;for(let k of ['agility','plate','regen','blockBonus','passion'])if(f[k])r[k]=(r[k]||0)+f[k];if(f.temporary){r.tempStr=(r.tempStr||0)+(f.s||0);r.tempAgility=(r.tempAgility||0)+(f.agility||0)}if(f.nextBlock){(r.nextBlockEffects??=[]).push(f.nextBlock);r.nextBlock=(r.nextBlock||0)+f.nextBlock}if(f.poisonDouble)r.poisonDouble=f.poisonTicks||2;if(f.retainBlock)r.retainBlock=true;if(f.heartbeat){r.heartbeat=true;r.heartbeatRefund=f.heartbeatRefund||1};if(wasHeartbeat){let total=(r.heartbeatCount||0)+c.cost;r.energy+=Math.floor(total/4)*(r.heartbeatRefund||1);r.heartbeatCount=total%4}if(f.draw)draw(f.draw);if(f.discard&&r.hand.length)r.pendingChoice={kind:'discard',remaining:f.discard};if(f.chooseExhaust){if(r.hand.length)r.pendingChoice={kind:'exhaust',remaining:f.chooseExhaust,draw:2*f.chooseExhaust};else draw(2*f.chooseExhaust)}if(typeof onCardResolved==='function')onCardResolved(r,c);if(r.kind==='boss')bossPlan(r);msg=c.name+'を使用。';if(r.enemies.every(e=>e.hp<=0)){r.pendingChoice=null;victory()}else render()};
function chooseHand(i){let r=S.run,p=r?.pendingChoice;if(busy||!p||p.inspect||i<0||i>=r.hand.length)return;let id=r.hand.splice(i,1)[0];if(p.kind==='exhaust')exhaustCard(r,id);else r.discard.push(id);p.remaining=(p.remaining||1)-1;if(p.remaining>0&&r.hand.length){render();return}if(p.breakTarget!=null&&r.enemies[p.breakTarget]){r.enemies[p.breakTarget].block=0;if(typeof clearArchiveReading==='function')clearArchiveReading(r.enemies[p.breakTarget]);};r.pendingChoice=null;r.pendingDiscard=0;if(p.draw)draw(p.draw);if(p.searchDraw&&r.draw.length&&r.hand.length<10)r.hunterChoice={kind:'search',remaining:Math.min(p.searchDraw,r.draw.length,10-r.hand.length)};render()}
const playOverhaul=play;play=async function(i){if(S.run?.pendingChoice||S.run?.potionTarget!=null)return;return playOverhaul(i)};
const chooseOverhaul=choose;choose=function(type){chooseOverhaul(type);let r=S.run;if(r?.mode==='battle'){for(let k of ['agility','plate','blockBonus','heartbeatCount','passion','tempStr','tempAgility'])r[k]=0;for(let k of ['heartbeat','retainBlock','poisonDouble'])r[k]=false;r.pendingChoice=null;r.pendingDiscard=0;r.potionTarget=null;r.generatedCards=[];r.nextBlockEffects=[];render()}};
function poisonLoss(e,r){let n=e.poison||0,ticks=r.poisonDouble===true?2:r.poisonDouble||1;return Array.from({length:ticks},(_,i)=>Math.max(0,n-i)).reduce((a,b)=>a+b,0)}
forecastDamage=function(r){let b=r.block||0,n=0;for(let e of r.enemies){if(e.hp<=poisonLoss(e,r)||e.intent!=='attack')continue;for(let h=0;h<(e.hits||1);h++){n+=Math.max(0,enemyAttack(e)-b);b=Math.max(0,b-enemyAttack(e))}}return n};
applyTurnStartBuffs=function(r){if(r.passion){r.hp=Math.max(0,r.hp-r.passion);if(r.hp<=0)return;for(let i=0;i<r.passion;i++)gainBlock(r,5,'passive')}for(let n of r.nextBlockEffects?.length?r.nextBlockEffects:(r.nextBlock?[r.nextBlock]:[]))gainBlock(r,n,'passive');r.nextBlockEffects=[];r.nextBlock=0;if(r.plate>0){gainBlock(r,r.plate,'passive');r.plate--}if(r.regen>0){r.hp=Math.min(r.max,r.hp+r.regen);r.regen--}};
endTurn=async function(){let r=S.run;if(busy||page!=='battle'||r.pendingChoice||r.pendingDiscard||r.potionTarget!=null)return;busy=true;expireGeneratedCards(r);r.str-=r.tempStr||0;r.agility=(r.agility||0)-(r.tempAgility||0);r.tempStr=0;r.tempAgility=0;r.discard.push(...r.hand);r.hand=[];for(let i=0;i<r.enemies.length;i++){let e=r.enemies[i];if(e.hp<=0)continue;e.block=0;for(let tick=0;tick<(r.poisonDouble===true?2:r.poisonDouble||1)&&e.hp>0;tick++)if(e.poison){let n=e.poison;e.hp=Math.max(0,e.hp-n);e.poison--;await animateEntity(i,'hit',n)}if(e.hp<=0){await animateEntity(i,'death');continue}if(e.intent==='attack'){await animateEntity(i,'attack',0,-1);for(let h=0;h<(e.hits||1);h++){let n=Math.max(0,e.atk-r.block);r.block=Math.max(0,r.block-e.atk);r.hp=Math.max(0,r.hp-n);if(n)await animateEntity('player','hit',n);if(r.hp<=0)break}}else if(e.intent==='guard')e.block=e.guardAmount||9;else e.atk+=3;if(r.hp<=0){await animateEntity('player','death');busy=false;finish(false);return}}if(r.enemies.every(e=>e.hp<=0)){busy=false;victory();return}r.turn++;if(!r.retainBlock)r.block=0;for(let x of r.relics)if(x.type==='b')gainBlock(r,3,'relic');r.energy=r.energyMax||3;applyTurnStartBuffs(r);if(r.hp<=0){await animateEntity('player','death');busy=false;finish(false);return}prepareEncounterTurn(r);if(r.kind==='boss')bossPlan(r);draw(5,true);busy=false;render()};
intent=e=>e.intent==='stunned'?'<strong>⏸ スタン</strong><small>行動不能</small>':e.intent==='attack'?`<strong>⚔ ${enemyAttack(e)}${e.hits>1?' × '+e.hits:''}</strong><small>${e.move||'攻撃'}</small>`:e.intent==='guard'?`<strong>◇ ${e.guardAmount||9}</strong><small>${e.move||'防御'}</small>`:'<strong>↑ 攻撃 +3</strong><small>強化</small>';
let pileView=null;
function showPile(kind){if(busy||!S.run||S.run.pendingChoice)return;pileView=kind;render()}
function closePile(){pileView=null;render()}
function recordRun(outcome){let r=S.run;if(!r||r.historyRecorded)return;r.historyRecorded=true;(S.history??=[]).unshift({date:new Date().toISOString(),outcome,floor:r.floor,hp:r.hp,max:r.max,packs:outcome==='retire'?0:r.packs,gold:outcome==='retire'?0:r.gold,deck:[...r.deck],relics:r.relics.map(x=>x.name)});S.history=S.history.slice(0,200)}
const finishHistory=finish;finish=function(win,ret=false){recordRun(win?'win':ret?'retire':'loss');pileView=null;finishHistory(win,ret)};
const retireHistory=confirmRetire;confirmRetire=function(){if(S.run&&retireDialog&&!busy)recordRun('retire');pileView=null;retireHistory()};
function historyHTML(){return `<div class="eyebrow">RUN ARCHIVE</div><h2>ランの履歴</h2><p>このブラウザに最新200件を保存します。更新前のランは記録されていません。</p>${S.history?.length?S.history.map(h=>`<details class="tile history-entry"><summary><strong>${{win:'王を撃破',loss:'ゲームオーバー',retire:'リタイア'}[h.outcome]}</strong>　${new Date(h.date).toLocaleString('ja-JP')}　／ 第${h.floor}層</summary><p>HP ${h.hp} / ${h.max}　持ち帰り：${h.packs}パック・${h.gold}金</p><p>遺物：${h.relics.join('、')||'なし'}</p><div class="cards">${[...new Set(h.deck)].sort(cardOrder).map(id=>card(id,'',`<span class="count">${h.deck.filter(x=>x===id).length}枚</span>`)).join('')}</div></details>`).join(''):'<div class="tile">ラン終了後、ここに記録されます。</div>'}`}
go=function(p){if(busy)return;if(p==='home'&&S.run)p=S.run.mode;if(p==='packs'&&S.run)return toast('パックは拠点で開封できます');if(p==='packs'||page==='packs')revealed=[];clearDrag();pileView=null;page=p;render()};
const battleOverhaul=battle;battle=function(){let r=S.run,html=battleOverhaul();html=html.replace('現在のブロックと毒による撃破を考慮した、敵ターンの予測HP減少量','ブロックと毒での撃破を考慮した予測被ダメージ（残りHPで上限を設けません）').replace('予測HP減少量','予測被ダメージ');let status='';for(let [k,n] of [['agility','守護'],['plate','プレート'],['blockBonus','ブロック効果']])if(r[k])status+=`<span class="status-help" tabindex="0">${n} ${r[k]>=0?'+':''}${r[k]}<aside class="tooltip">${keywords[n]||'ブロックを得る各効果への加算値。'}</aside></span>`;if(r.passion)status+=`<span class="status-help" tabindex="0">激情 ×${r.passion}<aside class="tooltip">ターン開始時、HPを${r.passion}失い、${5*r.passion}ブロックを得ます。</aside></span>`;if(r.retainBlock)status+='<span class="status-help">城壁：ブロック保持</span>';if(r.poisonDouble)status+='<span class="status-help">触媒：毒が2回発動</span>';html=html.replace('<div class="player-status">','<div class="player-status">'+status);html=html.replace(`山札 ${r.draw.length}　捨札 ${r.discard.length}　除外 ${exhaustedCount(r)}`,`<button onclick="showPile('draw')">山札 ${r.draw.length}</button> <button onclick="showPile('discard')">捨て札 ${r.discard.length}</button> <button onclick="showPile('exhausted')">除外 ${exhaustedCount(r)}</button>`);if(r.heartbeat)html=html.replace(/<span class="energy">([\s\S]*?)<\/span>/,`<div class="energy-stack"><span class="energy">$1</span><span class="heartbeat-meter" title="${r.heartbeatThreshold??4}消費するたびエナジー+${r.heartbeatRefund||1}。超過分を繰り越します。">♥ 鼓動：${r.heartbeatCount||0} / ${r.heartbeatThreshold??4}</span></div>`);if(r.pendingChoice&&r.pendingChoice.kind!=='recoverExcluded')html+=`<div class="hand-shade"></div><div class="hand-prompt" role="status">手札を1枚選んで${r.pendingChoice.kind==='exhaust'?'除外':'捨て札へ'}<small>残り ${r.pendingChoice.remaining||1}枚を選択すると続行します</small></div><button class="inspect-choice" onclick="toggleChoiceInspect()">${r.pendingChoice.inspect?'カード選択に戻る':'現在の状況を見る'}</button>`;return html};
function paintPoison(){if(page!=='battle'||!S.run)return;document.querySelectorAll('[data-entity]').forEach(el=>{let key=el.dataset.entity,e=key==='player'?S.run:S.run.enemies[+key],track=el.querySelector('.health-track');if(!track||!e)return;track.querySelector('.poison-preview')?.remove();let capacity=e.max+(key==='player'?(e.curseMaxLoss||0):0);let n=Math.min(e.hp,key==='player'?(e.poison||0):poisonLoss(e,S.run));if(n>0)track.insertAdjacentHTML('beforeend',`<i class="poison-preview" title="毒による次のHP減少 ${n}" style="left:${(e.hp-n)/capacity*100}%;width:${n/capacity*100}%"></i>`)})}
const setHealthOverhaul=setUnitHealth;setUnitHealth=function(...args){setHealthOverhaul(...args);paintPoison()};
const renderOverhaul=render;render=function(){if(globalThis.ASHBOUND_LOADING)return;renderOverhaul();$('nav').innerHTML+=`<button class="${page==='history'?'active':''}" onclick="go('history')">履歴</button>`;if(page==='history')$('app').innerHTML=historyHTML();let selecting=page==='battle'&&!!S.run?.pendingChoice&&S.run.pendingChoice.kind!=='recoverExcluded';document.body.classList.toggle('choosing-hand',selecting);document.body.classList.toggle('inspecting-choice',selecting&&!!S.run.pendingChoice.inspect);if(selecting&&!S.run.pendingChoice.inspect)document.querySelectorAll('.hand .card').forEach((el,i)=>{el.onclick=()=>chooseHand(i);el.classList.remove('unplayable');el.setAttribute('aria-label',C[S.run.hand[i]].name+'を選ぶ')});if(page==='battle'&&pileView){let r=S.run,ids=[...(r[pileView]||[])].sort(cardOrder);$('app').insertAdjacentHTML('beforeend',`<div class="pile-overlay" role="dialog" aria-modal="true"><div class="pile-panel"><div class="toolbar"><h2>${{draw:'山札',discard:'捨て札',exhausted:'除外'}[pileView]}・${ids.length}枚</h2><button onclick="closePile()">閉じる ×</button></div>${pileView==='draw'?'<p>種類順で表示しています。引く順番ではありません。</p>':''}<div class="cards">${ids.map(id=>card(id)).join('')||'<p>カードはありません。</p>'}</div></div></div>`)}paintPoison();save()};
// Remove retired cards without reducing the player's collection or deck size.
function migrateIDs(ids){return ids?.map(id=>id===48?50:id)}
if(S.collection[48]){S.collection[50]=(S.collection[50]||0)+S.collection[48];delete S.collection[48]}S.deck=migrateIDs(S.deck);if(S.run){let r=S.run;for(let k of ['deck','hand','draw','discard','exhausted','rewardCards'])if(r[k])r[k]=migrateIDs(r[k]);if(r.pendingDiscard){r.pendingChoice={kind:'discard',remaining:r.pendingDiscard};r.pendingDiscard=0}if(r.blockEngine){r.blockBonus=(r.blockBonus||0)+4;r.blockEngine=0}for(let e of r.enemies||[])if(e.behavior==='plated'&&e.configRev!==3){e.atk=e.baseAtk+Math.max(0,r.turn-2);e.ability+=' 3ターン目以降、毎ターン攻撃+1。'}}
function toggleChoiceInspect(){let p=S.run?.pendingChoice;if(page!=='battle'||!p)return;clearDrag();p.inspect=!p.inspect;render()}
for(let eventType of ['click','pointerdown','contextmenu','keydown'])document.addEventListener(eventType,e=>{if(page==='battle'&&S.run?.pendingChoice?.inspect&&!e.target.closest?.('.inspect-choice')&&!e.target.closest?.('.battle-presentation')){if(eventType==='keydown'&&!['Enter',' ','Spacebar'].includes(e.key))return;e.preventDefault();e.stopImmediatePropagation()}},true);

